ALTER TABLE customers ADD COLUMN archived_at TEXT;
ALTER TABLE customers ADD COLUMN phone TEXT NOT NULL DEFAULT '';
ALTER TABLE customers ADD COLUMN address TEXT NOT NULL DEFAULT '';
ALTER TABLE customers ADD COLUMN tags TEXT NOT NULL DEFAULT '';
ALTER TABLE user_profiles ADD COLUMN staff_role TEXT NOT NULL DEFAULT 'owner' CHECK(staff_role IN ('owner','receptionist','groomer'));
ALTER TABLE services ADD COLUMN duration_minutes INTEGER NOT NULL DEFAULT 60 CHECK(duration_minutes BETWEEN 15 AND 480 AND duration_minutes % 15 = 0);
ALTER TABLE services ADD COLUMN buffer_minutes INTEGER NOT NULL DEFAULT 0 CHECK(buffer_minutes BETWEEN 0 AND 120 AND buffer_minutes % 15 = 0);
ALTER TABLE bookings ADD COLUMN groomer_id TEXT;
ALTER TABLE bookings ADD COLUMN duration_minutes INTEGER NOT NULL DEFAULT 60;
ALTER TABLE bookings ADD COLUMN buffer_minutes INTEGER NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN stage TEXT NOT NULL DEFAULT 'scheduled' CHECK(stage IN ('scheduled','arrived','grooming','ready','collected'));
CREATE TABLE salon_settings(id INTEGER PRIMARY KEY CHECK(id=1), business_name TEXT NOT NULL DEFAULT 'PetMan', address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', invoice_footer TEXT NOT NULL DEFAULT 'Thank you for visiting.', opening TEXT NOT NULL DEFAULT '09:00', closing TEXT NOT NULL DEFAULT '17:00', closed_weekdays TEXT NOT NULL DEFAULT '', minimum_notice_minutes INTEGER NOT NULL DEFAULT 60);
INSERT INTO salon_settings(id) VALUES(1);
CREATE TABLE groomers(id TEXT PRIMARY KEY, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, opening TEXT NOT NULL DEFAULT '09:00', closing TEXT NOT NULL DEFAULT '17:00', closed_weekdays TEXT NOT NULL DEFAULT '', break_start TEXT NOT NULL DEFAULT '', break_end TEXT NOT NULL DEFAULT '');
INSERT INTO groomers(id,name) VALUES('salon','Salon');
CREATE TABLE salon_closures(date TEXT PRIMARY KEY, reason TEXT NOT NULL DEFAULT 'Closed');
CREATE TABLE booking_occupancy(booking_id TEXT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, date TEXT NOT NULL, slot TEXT NOT NULL, groomer_id TEXT NOT NULL, PRIMARY KEY(date,slot,groomer_id));
INSERT INTO booking_occupancy(booking_id,date,slot,groomer_id) SELECT b.id,b.date,printf('%02d:%02d',(CAST(substr(b.slot,1,2) AS INTEGER)*60+CAST(substr(b.slot,4,2) AS INTEGER)+q.n*15)/60,(CAST(substr(b.slot,1,2) AS INTEGER)*60+CAST(substr(b.slot,4,2) AS INTEGER)+q.n*15)%60),'salon' FROM bookings b CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3) q WHERE b.status!='cancelled';
UPDATE bookings SET groomer_id='salon' WHERE groomer_id IS NULL;
DROP INDEX booking_slot;
CREATE INDEX bookings_day ON bookings(date,status);
CREATE TABLE customer_notes(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), body TEXT NOT NULL, actor_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE care_tasks(id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, due_date TEXT NOT NULL, assigned_to TEXT REFERENCES user_profiles(id), completed_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX care_tasks_due ON care_tasks(completed_at,due_date);
CREATE TABLE saved_views(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user_profiles(id), name TEXT NOT NULL, query TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices(id TEXT PRIMARY KEY, number INTEGER NOT NULL UNIQUE, customer_id TEXT NOT NULL REFERENCES customers(id), customer_name TEXT NOT NULL, customer_address TEXT NOT NULL DEFAULT '', business_snapshot TEXT NOT NULL, issued_date TEXT NOT NULL, due_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'issued' CHECK(status IN ('issued','void')), subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0), discount_cents INTEGER NOT NULL DEFAULT 0 CHECK(discount_cents>=0), tax_cents INTEGER NOT NULL DEFAULT 0 CHECK(tax_cents>=0), total_cents INTEGER NOT NULL CHECK(total_cents>=0), notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoice_items(id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), description TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), unit_cents INTEGER NOT NULL CHECK(unit_cents>=0));
CREATE TABLE invoice_payments(id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), kind TEXT NOT NULL CHECK(kind IN ('payment','refund')), amount_cents INTEGER NOT NULL CHECK(amount_cents>0), method TEXT NOT NULL CHECK(method IN ('cash','bank_transfer','card','other')), reference TEXT NOT NULL DEFAULT '', received_date TEXT NOT NULL, actor_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX invoices_customer ON invoices(customer_id,issued_date);
CREATE INDEX invoice_payments_invoice ON invoice_payments(invoice_id);
CREATE TRIGGER invoice_payment_guard BEFORE INSERT ON invoice_payments BEGIN
 SELECT CASE WHEN (SELECT status FROM invoices WHERE id=NEW.invoice_id)!='issued' THEN RAISE(ABORT,'Invoice is void') END;
 SELECT CASE WHEN NEW.kind='payment' AND NEW.amount_cents > (SELECT total_cents-COALESCE((SELECT SUM(CASE WHEN kind='payment' THEN amount_cents ELSE -amount_cents END) FROM invoice_payments WHERE invoice_id=NEW.invoice_id),0) FROM invoices WHERE id=NEW.invoice_id) THEN RAISE(ABORT,'Payment exceeds balance') END;
 SELECT CASE WHEN NEW.kind='refund' AND NEW.amount_cents > COALESCE((SELECT SUM(CASE WHEN kind='payment' THEN amount_cents ELSE -amount_cents END) FROM invoice_payments WHERE invoice_id=NEW.invoice_id),0) THEN RAISE(ABORT,'Refund exceeds collected amount') END;
END;
